toad_implementation.code_blueprint:
canvas {
  size: 800px 960px;
  fill: #FFFFFF;
  font-family: "Libre Baskerville, serif";
}

>paper = #FFFFFF;
>ink = #111111;
>kickerRed = #E63946;
>divider = #E5E7EB;

rect #topKickerStripe {
  at: top left of canvas offset 56px 48px;
  size: 688px 3px;
  fill: >kickerRed;
}

text #kickerText {
  at: below #topKickerStripe offset 12px;
  content: "INVESTIGATIV // REPORTAGE DER WOCHE";
  font-size: 11px;
  font-weight: 700;
  color: >kickerRed;
}

text #magazineHeadline {
  at: below #kickerText offset 12px;
  size: 688px;
  content: "Mapping the Future";
  font-size: 42px;
  font-weight: 700;
  color: >ink;
}

text #subLead {
  at: below #magazineHeadline offset 16px;
  size: 688px;
  content: "How artificial intelligence and autonomous systems challenge the foundations of modern democracy — an analytical audit.";
  font-size: 16px;
  color: #4B5563;
}

rect #pullQuoteBox {
  at: below #subLead offset 40px;
  size: 688px 120px;
  fill: #F9FAFB;
  stroke: >kickerRed;
  stroke-width: 3px;
}

text #quoteContent {
  at: center of #pullQuoteBox;
  size: 620px;
  content: "“Whoever controls the algorithms shapes the thoughts of billions in subsecond cycles.”";
  font-size: 18px;
  font-style: italic;
  color: >ink;
}

text #byline {
  at: bottom left of canvas offset 56px -48px;
  content: "TEXT: TOBIAS BRANDSTÄTTER • FOTOS: CHLOÉ BEAUCHAMP";
  font-size: 10px;
  font-weight: 700;
  color: #9CA3AF;
}
